using UnityEngine;
using Mirror;

// Simple networked player. Authority runs input and server synchronizes position.
// This is intentionally minimal — replace with CharacterController, Rigidbody, or a custom controller.
public class NetworkPlayer : NetworkBehaviour
{
    [SyncVar] private Vector3 syncedPosition;
    [SyncVar] private Quaternion syncedRotation;

    public float moveSpeed = 5f;

    void Update()
    {
        if (isLocalPlayer)
        {
            HandleInput();
            CmdSyncTransform(transform.position, transform.rotation);
        }
        else
        {
            // Smoothly interpolate remote players
            transform.position = Vector3.Lerp(transform.position, syncedPosition, 10f * Time.deltaTime);
            transform.rotation = Quaternion.Slerp(transform.rotation, syncedRotation, 10f * Time.deltaTime);
        }
    }

    void HandleInput()
    {
        float h = Input.GetAxis("Horizontal");
        float v = Input.GetAxis("Vertical");
        Vector3 dir = new Vector3(h, 0, v);
        if (dir.sqrMagnitude > 0.001f)
        {
            transform.Translate(dir.normalized * moveSpeed * Time.deltaTime, Space.World);
        }
    }

    [Command]
    void CmdSyncTransform(Vector3 pos, Quaternion rot)
    {
        // Basic server reconciliation: accept client transform for now.
        syncedPosition = pos;
        syncedRotation = rot;
    }
}
