using UnityEngine;

// Local grappling hook prototype (non-networked).
// Networking considerations: replicate grapple start/stop, reconcile rope physics server-side or autoritative hooks.
public class GrapplingHook : MonoBehaviour
{
    public Transform cameraTransform;
    public float maxDistance = 25f;
    public LineRenderer line;
    private Vector3 grapplePoint;
    private bool grappling;

    void Update()
    {
        if (Input.GetButtonDown("Fire1"))
        {
            TryGrapple();
        }
        if (Input.GetButtonUp("Fire1"))
        {
            ReleaseGrapple();
        }

        if (grappling)
        {
            // Simple pull towards point
            Vector3 dir = (grapplePoint - transform.position).normalized;
            transform.position += dir * 10f * Time.deltaTime;
            if (Vector3.Distance(transform.position, grapplePoint) < 1.5f) ReleaseGrapple();
            UpdateLine();
        }
    }

    void TryGrapple()
    {
        Ray ray = new Ray(cameraTransform.position, cameraTransform.forward);
        if (Physics.Raycast(ray, out RaycastHit hit, maxDistance))
        {
            grappling = true;
            grapplePoint = hit.point;
            if (line != null) { line.positionCount = 2; UpdateLine(); }
        }
    }

    void ReleaseGrapple()
    {
        grappling = false;
        if (line != null) line.positionCount = 0;
    }

    void UpdateLine()
    {
        if (line != null)
        {
            line.SetPosition(0, transform.position);
            line.SetPosition(1, grapplePoint);
        }
    }
}
