// UI: Trust meter and smartphone overlay (non-modal)
export function createUI(opts = {}) {
  const hud = document.createElement('div');
  hud.className = 'hud';
  hud.innerHTML = `
    <div class="labels">Trust Meter</div>
    <div class="trust"><i style="width:50%"></i></div>
  `;
  document.body.appendChild(hud);

  const phone = document.createElement('div');
  phone.className = 'smartphone';
  phone.innerHTML = `
    <h4>Trust Protocol Phone</h4>
    <div id="phone-content">Messages and fast-travel (non-modal)</div>
    <div style="margin-top:8px">
      <button id="fake-msg">Send photo code</button>
      <button id="toggle-phone">Hide</button>
    </div>
  `;
  document.body.appendChild(phone);

  document.getElementById('fake-msg').addEventListener('click', ()=>{
    const el = document.getElementById('phone-content');
    el.textContent = 'Photo code sent to teammates (simulated)';
    // small feedback
  });
  document.getElementById('toggle-phone').addEventListener('click', ()=>{
    phone.classList.toggle('hidden');
    if (opts.onTogglePhone) opts.onTogglePhone();
  });

  const ctrl = document.createElement('div');
  ctrl.className = 'controls';
  ctrl.innerHTML = `<b>Controls</b><div>WASD: move • Click: Grapple • Shift: sprint</div>`;
  document.body.appendChild(ctrl);
}

export function setTrust(value) {
  const el = document.querySelector('.trust > i');
  if (el) {
    const pct = Math.max(0, Math.min(100, value));
    el.style.width = pct + '%';
  }
}
