export async function connect(url = 'ws://localhost:3000') {
  try {
    const socket = new WebSocket(url);
    socket.addEventListener('open', () => console.log('Network: connected'));
    socket.addEventListener('message', (m) => console.log('Network msg', m.data));
    return {
      send: (t) => socket.send(JSON.stringify(t)),
      raw: socket
    };
  } catch (err) {
    console.warn('Network: connect failed', err);
    return {
      send: () => console.warn('Network stub: send ignored'),
      raw: null
    };
  }
}
