function buildHud() {
  const hud = document.createElement('div');
  hud.className = 'hud';

  hud.innerHTML = `
    <div class="hud-panel">
      <div class="brand">Trust Protocol</div>
      <div class="meter-row">
        <div class="meter-label">Trust</div>
        <div class="meter">
          <div class="meter-fill" id="trust-fill"></div>
        </div>
      </div>
      <div class="status" id="status-text">Mission: breach the temple and keep the crew aligned.</div>
    </div>
  `;

  document.body.appendChild(hud);

  return {
    setTrust: (value) => {
      const meterFill = document.getElementById('trust-fill');
      meterFill.style.width = `${Math.max(0, Math.min(100, value))}%`;
    },
    setStatus: (text) => {
      const statusText = document.getElementById('status-text');
      statusText.textContent = `Mission: ${text}`;
    }
  };
}

function buildPhone() {
  const phone = document.createElement('div');
  phone.className = 'phone';

  phone.innerHTML = `
    <div class="phone-header">
      <span>Trust Phone</span>
      <span class="phone-close" id="close-phone">✕</span>
    </div>
    <div class="phone-body">
      <div>Criminal intel: Temple lock active.</div>
      <ul>
        <li>Blackhujus: tank / brute</li>
        <li>Mr. PING: grappling / stealth</li>
        <li>Merhujus: engineer / support</li>
      </ul>
      <button id="phone-btn">Send photo code</button>
    </div>
  `;

  const closeBtn = phone.querySelector('#close-phone');
  closeBtn.addEventListener('click', () => {
    phone.classList.add('hidden');
  });

  const sendBtn = phone.querySelector('#phone-btn');
  sendBtn.addEventListener('click', () => {
    const body = phone.querySelector('.phone-body');
    body.innerHTML = `
      <div>Photo code sent.</div>
      <ul>
        <li>Team ping: route clear</li>
        <li>Safe house: holding</li>
      </ul>
    `;
  });

  document.body.appendChild(phone);

  return {
    toggle: () => phone.classList.toggle('hidden'),
    show: () => phone.classList.remove('hidden'),
    hide: () => phone.classList.add('hidden')
  };
}

function buildNotice() {
  const notice = document.createElement('div');
  notice.className = 'notice';
  document.body.appendChild(notice);

  return {
    show: (text) => {
      notice.textContent = text;
      notice.classList.add('visible');
      clearTimeout(notice._timer);
      notice._timer = setTimeout(() => {
        notice.classList.remove('visible');
      }, 1800);
    }
  };
}

function buildControls() {
  const div = document.createElement('div');
  div.className = 'controls';
  div.innerHTML = `
    <strong>Controls</strong><br />
    WASD / Arrows: move<br />
    Click: grapple<br />
    Shift: sprint<br />
    T: phone
  `;
  document.body.appendChild(div);
}

export function setupUI() {
  const hud = buildHud();
  const phone = buildPhone();
  const notice = buildNotice();
  buildControls();

  window.addEventListener('keydown', (event) => {
    if (event.key.toLowerCase() === 't') {
      phone.toggle();
    }
  });

  return { ...hud, notice, phone };
}
