```js
import * as THREE from 'three';
import { setupUI } from './ui.js';

export function startGame() {
  const app = document.getElementById('app');

  const renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  app.appendChild(renderer.domElement);

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x0c1620);

  const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 200);
  camera.position.set(0, 14, 22);

  const hemi = new THREE.HemisphereLight(0xdfeaf7, 0x102737, 1.2);
  scene.add(hemi);

  const dir = new THREE.DirectionalLight(0xffffff, 1.1);
  dir.position.set(8, 18, 10);
  scene.add(dir);

  // Ground
  const ground = new THREE.Mesh(
    new THREE.PlaneGeometry(80, 80),
    new THREE.MeshStandardMaterial({ color: 0x264d3c })
  );
  ground.rotation.x = -Math.PI / 2;
  ground.position.y = -0.5;
  scene.add(ground);

  // Temple walls / obstacles
  const wallMaterial = new THREE.MeshStandardMaterial({ color: 0x34495e });
  const wallData = [
    { x: 0, y: 2.5, z: -18, w: 32, h: 5, d: 2 },
    { x: -12, y: 2.5, z: 0, w: 2, h: 5, d: 26 },
    { x: 12, y: 2.5, z: 0, w: 2, h: 5, d: 26 },
    { x: 0, y: 2.5, z: 18, w: 32, h: 5, d: 2 },
  ];

  wallData.forEach(({ x, y, z, w, h, d }) => {
    const wall = new THREE.Mesh(
      new THREE.BoxGeometry(w, h, d),
      wallMaterial
    );
    wall.position.set(x, y, z);
    scene.add(wall);
  });

  // Exit point
  const exit = new THREE.Mesh(
    new THREE.BoxGeometry(4, 4, 1),
    new THREE.MeshStandardMaterial({ color: 0x67e8f9, emissive: 0x0f3f4d })
  );
  exit.position.set(0, 2, 18.5);
  scene.add(exit);

  // Heroes
  const heroDefs = [
    { name: 'Mr. PING', color: 0x5dd6ff, x: -7, z: 0 },
    { name: 'Blackhujus', color: 0xffa14d, x: 0, z: 0 },
    { name: 'Merhujus', color: 0x8b5cf6, x: 7, z: 0 },
  ];

  const heroes = heroDefs.map((def, index) => {
    const mesh = new THREE.Mesh(
      new THREE.BoxGeometry(1.8, 2.2, 1.8),
      new THREE.MeshStandardMaterial({ color: def.color })
    );
    mesh.position.set(def.x, 1.1, def.z);
    mesh.userData = { name: def.name, index };
    scene.add(mesh);
    return mesh;
  });

  const player = heroes[0];
  const playerRadius = 1.1;

  // Interactables
  const switchPositions = [
    new THREE.Vector3(-9, 1, -12),
    new THREE.Vector3(9, 1, -12),
    new THREE.Vector3(0, 1, 12),
  ];

  const switches = switchPositions.map((pos, i) => {
    const mesh = new THREE.Mesh(
      new THREE.CylinderGeometry(0.75, 0.75, 0.4, 18),
      new THREE.MeshStandardMaterial({ color: i % 2 === 0 ? 0xff7a7a : 0xffd166 })
    );
    mesh.position.copy(pos);
    mesh.rotation.x = Math.PI / 2;
    mesh.userData.active = false;
    scene.add(mesh);
    return mesh;
  });

  const loot = new THREE.Mesh(
    new THREE.SphereGeometry(0.6, 20, 20),
    new THREE.MeshStandardMaterial({ color: 0xffd166, emissive: 0x514302 })
  );
  loot.position.set(0, 1.2, -8);
  scene.add(loot);

  // UI
  const ui = setupUI();
  let trust = 68;
  ui.setTrust(trust);
  ui.setStatus('Reach the temple exit and activate all switches.');

  const notice = ui.notice;

  // Controls / actions
  const keys = { w: false, a: false, s: false, d: false, shift: false };
  window.addEventListener('keydown', (event) => {
    const key = event.key.toLowerCase();
    if (key in keys) {
      keys[key] = true;
    }
  });
  window.addEventListener('keyup', (event) => {
    const key = event.key.toLowerCase();
    if (key in keys) {
      keys[key] = false;
    }
  });

  const pointer = new THREE.Vector2();
  let grappleTarget = null;
  const lineGeo = new THREE.BufferGeometry();
  const lineMat = new THREE.LineBasicMaterial({ color: 0x67e8f9 });
  const line = new THREE.Line(lineGeo, lineMat);
  line.visible = false;
  scene.add(line);

  window.addEventListener('pointerdown', (event) => {
    pointer.x = (event.clientX / window.innerWidth) * 2 - 1;
    pointer.y = -(event.clientY / window.innerHeight) * 2 + 1;

    const raycaster = new THREE.Raycaster();
    raycaster.setFromCamera(pointer, camera);
    const groundHit = raycaster.intersectObject(ground);

    if (groundHit.length) {
      grappleTarget = groundHit[0].point.clone();
      const points = [player.position.clone(), grappleTarget.clone()];
      lineGeo.setFromPoints(points);
      line.visible = true;
    }
  });

  const clock = new THREE.Clock();

  function clamp(value, min, max) {
    return Math.min(Math.max(value, min), max);
  }

  function updatePlayer(dt) {
    const moveAccel = keys.shift ? 12 : 7;
    const newDir = new THREE.Vector3();
    if (keys.w) newDir.z -= 1;
    if (keys.s) newDir.z += 1;
    if (keys.a) newDir.x -= 1;
    if (keys.d) newDir.x += 1;

    if (newDir.lengthSq() > 0) {
      newDir.normalize();
      player.position.x += newDir.x * moveAccel * dt;
      player.position.z += newDir.z * moveAccel * dt;
    }

    // Bound movement
    player.position.x = clamp(player.position.x, -18, 18);
    player.position.z = clamp(player.position.z, -18, 18);

    if (grappleTarget) {
      const toTarget = new THREE.Vector3().subVectors(grappleTarget, player.position);
      const dist = toTarget.length();
      if (dist > 0.5) {
        toTarget.normalize();
        player.position.addScaledVector(toTarget, 10 * dt);
        const points = [player.position.clone(), grappleTarget.clone()];
        lineGeo.setFromPoints(points);
      } else {
        grappleTarget = null;
        line.visible = false;
      }
    }

    // Switch interaction
    switches.forEach((switchMesh) => {
      const distance = player.position.distanceTo(switchMesh.position);
      if (distance < 2.1 && !switchMesh.userData.active) {
        switchMesh.userData.active = true;
        switchMesh.material.color.setHex(0x6ee7b7);
        notice.show('Switch activated.');
        trust = clamp(trust + 8, 0, 100);
        ui.setTrust(trust);
      }
    });

    // loot pickup
    const lootDist = player.position.distanceTo(loot.position);
    if (lootDist < 2.0) {
      trust = clamp(trust - 12, 0, 100);
      ui.setTrust(trust);
      notice.show('Loot stolen. Trust dropped.');
      loot.position.set((Math.random() - 0.5) * 20, 1.2, (Math.random() - 0.5) * 18);
    }

    const exitDist = player.position.distanceTo(exit.position);
    const switchesActive = switches.every((s) => s.userData.active);
    if (exitDist < 3.5) {
      if (switchesActive) {
        ui.setStatus('Temple unlocked. Crew mission complete.');
        notice.show('Temple secured.');
      } else {
        ui.setStatus('Need all switches active before escape.');
      }
    } else if (switchesActive) {
      ui.setStatus('All switches active. Exit is open.');
    } else {
      ui.setStatus('Reach the temple exit and activate all switches.');
    }
  }

  function render() {
    const dt = clock.getDelta();

    updatePlayer(dt);

    const lookAtTarget = new THREE.Vector3(player.position.x, 1.5, player.position.z);
    camera.position.lerp(new THREE.Vector3(player.position.x, 12, 20), 0.08);
    camera.lookAt(lookAtTarget);

    renderer.render(scene, camera);
    requestAnimationFrame(render);
  }

  render();

  window.addEventListener('resize', () => {
    renderer.setSize(window.innerWidth, window.innerHeight);
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
  });
}
