    }
  }
};

const keys = {};
const gameState = {
  time: 0,
  selectedHero: 'blackhujus',
  activePhone: false,
  shaders: [],
  relics: [],
  enemies: [],
  projectiles: [],
  particles: [],
  trust: 82,
  gateOpen: false,
  gateGlow: 0,
