  defeat: false,
  missionStage: 'relics',
  wave: 1,
  lastSpawn: 0,
};

const heroes = {
  blackhujus: {
    ...HERO_DEFS.blackhujus,
    x: world.playerSpawn.x,
    y: world.playerSpawn.y,
    radius: 20,
    hp: 135,
    maxHp: 135,
    facing: { x: 1, y: 0 },
    cooldowns: { primary: 0, secondary: 0 },
