```js name=src/main.js
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');

const trustFill = document.getElementById('trust-fill');
const trustText = document.getElementById('trust-text');
const phone = document.getElementById('phone');
const heroButtons = [...document.querySelectorAll('.hero-btn')];

const world = {
  width: 1600,
  height: 900,
  gravity: 0.55,
  floorY: 680,
  platforms: [
    { x: 0, y: 720, w: 1600, h: 200, type: 'ground' },
    { x: 160, y: 610, w: 240, h: 20, type: 'platform' },
    { x: 510, y: 540, w: 180, h: 18, type: 'platform' },
    { x: 850, y: 470, w: 200, h: 18, type: 'platform' },
    { x: 1160, y: 560, w: 220, h: 18, type: 'platform' },
    { x: 960, y: 360, w: 140, h: 14, type: 'platform' },
    { x: 1220, y: 300, w: 170, h: 12, type: 'platform' }
  ],
  enemies: [
    { x: 620, y: 680, w: 26, h: 26, hp: 2, kind: 'guard' },
    { x: 930, y: 680, w: 26, h: 26, hp: 2, kind: 'guard' },
    { x: 1280, y: 680, w: 26, h: 26, hp: 2, kind: 'guard' }
  ],
  pickups: [
    { x: 250, y: 560, w: 16, h: 16, type: 'coin' },
    { x: 590, y: 500, w: 16, h: 16, type: 'coin' },
    { x: 1300, y: 520, w: 18, h: 18, type: 'coin' },
    { x: 1420, y: 255, w: 18, h: 18, type: 'machete' }
  ],
  keyDoor: { x: 1490, y: 250, w: 24, h: 100 }
};

const heroes = [
  {
    id: 'blackhujus',
    name: 'Blackhujus',
    color: '#fbbf24',
    x: 90,
    y: 620,
    w: 30,
    h: 54,
    vx: 0,
    vy: 0,
    speed: 2.7,
    jump: 11,
    hp: 100,
    ability: 'Mighty Slam',
    unlocked: true
  },
  {
    id: 'ping',
    name: 'Mr. PING',
    color: '#67e8f9',
    x: 120,
    y: 620,
    w: 24,
    h: 48,
    vx: 0,
    vy: 0,
    speed: 3.6,
    jump: 12,
    hp: 100,
    ability: 'Grapple',
    unlocked: true
  },
  {
    id: 'merhujus',
    name: 'Merhujus',
    color: '#a78bfa',
    x: 150,
    y: 620,
    w: 26,
    h: 50,
    vx: 0,
    vy: 0,
    speed: 2.9,
    jump: 11.8,
    hp: 100,
    ability: 'Bridge Build',
    unlocked: true
  }
];

let activeHeroIndex = 0;
let trust = 62;
let phoneOpen = false;
let keys = {
  left: false,
  right: false,
  jump: false,
  attack: false,
  phone: false
};

function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

function updateTrustUI() {
  const pct = clamp(trust, 0, 100);
  trustFill.style.width = `${pct}%`;
  trustText.textContent = pct > 75 ? 'High Team Trust' : pct > 45 ? 'Stable' : 'Critical';
  if (pct < 25) {
    trustText.style.color = '#fecaca';
  } else if (pct > 75) {
    trustText.style.color = '#d1fae5';
  } else {
    trustText.style.color = '#fef3c7';
  }
}

function getActiveHero() {
  return heroes[activeHeroIndex];
}

function switchHero(index) {
  activeHeroIndex = index;
  heroButtons.forEach((btn, i) => {
    btn.classList.toggle('active', i === index);
  });
}

function togglePhone() {
  phoneOpen = !phoneOpen;
  phone.classList.toggle('hidden', !phoneOpen);
}

function handleInput() {
  const hero = getActiveHero();

  if (keys.left) hero.vx = -hero.speed;
  else if (keys.right) hero.vx = hero.speed;
  else hero.vx *= 0.72;

  if (keys.jump && hero.y + hero.h >= world.floorY - 1) {
    hero.vy = -hero.jump;
    keys.jump = false;
  }

  if (keys.attack) {
    if (hero.id === 'blackhujus') {
      for (const enemy of world.enemies) {
        if (Math.abs(enemy.x - hero.x) < 80 && Math.abs(enemy.y - hero.y) < 70) {
          enemy.hp -= 1;
          trust += 2;
        }
      }
    }

    if (hero.id === 'ping') {
      const target = world.pickups.find(p => p.type === 'machete');
      if (target && Math.abs(target.x - hero.x) < 120) {
        trust += 6;
      }
    }

    if (hero.id === 'merhujus') {
      const nearDoor = world.keyDoor.x - hero.x < 110 && world.keyDoor.x - hero.x > -80;
      if (nearDoor) {
        trust += 5;
      }
    }
    keys.attack = false;
  }

  if (hero.id === 'ping' && keys.jump && hero.y < 500) {
    hero.x += hero.vx * 0.7;
  }
}

function updatePhysics() {
  for (const hero of heroes) {
    hero.vy += world.gravity;
    hero.x += hero.vx;
    hero.y += hero.vy;

    if (hero.x < 0) hero.x = 0;
    if (hero.x + hero.w > world.width) hero.x = world.width - hero.w;

    const ground = world.platforms.find(p => hero.y + hero.h <= p.y + 10 && hero.y + hero.h >= p.y - 20 && hero.x + hero.w > p.x && hero.x < p.x + p.w && hero.vy > 0);
    if (ground) {
      hero.y = ground.y - hero.h;
      hero.vy = 0;
    }

    if (hero.y + hero.h > world.floorY) {
      hero.y = world.floorY - hero.h;
      hero.vy = 0;
    }

    if (hero.x > world.keyDoor.x && hero.x < world.keyDoor.x + world.keyDoor.w + 40) {
      trust = clamp(trust - 0.08, 0, 100);
    }
  }

  for (const enemy of world.enemies) {
    if (enemy.hp <= 0) continue;
    const near = heroes.some(hero => {
      return Math.abs(hero.x - enemy.x) < 55 && Math.abs(hero.y - enemy.y) < 60;
    });
    if (near) {
      enemy.x += Math.sin(Date.now() * 0.01 + enemy.x) * 0.6;
    }
  }

  world.enemies = world.enemies.filter(enemy => enemy.hp > 0);
  world.pickups = world.pickups.filter(pickup => {
    const touched = heroes.some(hero => {
      return hero.x + hero.w > pickup.x && hero.x < pickup.x + pickup.w &&
             hero.y + hero.h > pickup.y && hero.y < pickup.y + pickup.h;
    });
    if (touched && pickup.type === 'coin') {
      trust = clamp(trust + 4, 0, 100);
      return false;
    }
    if (touched && pickup.type === 'machete') {
      trust = clamp(trust + 12, 0, 100);
      return false;
    }
    return true;
  });

  if (heroes[0].x > 1420 && heroes[1].x > 1420 && heroes[2].x > 1420) {
    trust = clamp(trust + 0.1, 0, 100);
  }
}

function drawBackground() {
  ctx.fillStyle = '#0a1429';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  const sky = ctx.createLinearGradient(0, 0, 0, canvas.height);
  sky.addColorStop(0, '#1f2a44');
  sky.addColorStop(0.55, '#18233d');
  sky.addColorStop(1, '#101827');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  for (let i = 0; i < 14; i++) {
    ctx.fillStyle = 'rgba(255,255,255,0.06)';
    ctx.fillRect(i * 110 + 30, 80 + (i % 3) * 25, 2, 130);
  }

  ctx.fillStyle = 'rgba(255,255,255,0.04)';
  for (let i = 0; i < 26; i++) {
    const x = (i * 87) % canvas.width;
    const y = 120 + (i % 5) * 40;
    ctx.fillRect(x, y, 100, 2);
  }
}

function drawPlatforms() {
  for (const p of world.platforms) {
    ctx.fillStyle = p.type === 'ground' ? '#1f2937' : '#243b53';
    ctx.fillRect(p.x, p.y, p.w, p.h);

    ctx.strokeStyle = 'rgba(103,232,249,0.2)';
    ctx.strokeRect(p.x, p.y, p.w, p.h);
  }

  ctx.fillStyle = '#34d399';
  ctx.fillRect(world.keyDoor.x, world.keyDoor.y, world.keyDoor.w, world.keyDoor.h);
  ctx.fillStyle = '#fbbf24';
  ctx.fillRect(world.keyDoor.x + 5, world.keyDoor.y + 12, 14, 16);

  for (const enemy of world.enemies) {
    ctx.fillStyle = '#ef4444';
    ctx.fillRect(enemy.x, enemy.y, enemy.w, enemy.h);
    ctx.fillStyle = '#111827';
    ctx.fillRect(enemy.x, enemy.y - 8, enemy.w, 5);
    ctx.fillStyle = '#fbbf24';
    ctx.fillRect(enemy.x, enemy.y - 8, enemy.w * (enemy.hp / 2), 5);
  }

  for (const pickup of world.pickups) {
    ctx.fillStyle = pickup.type === 'coin' ? '#fbbf24' : '#67e8f9';
    ctx.fillRect(pickup.x, pickup.y, pickup.w, pickup.h);
  }
}

function drawHero(hero, isActive) {
  ctx.fillStyle = hero.color;
  ctx.fillRect(hero.x, hero.y, hero.w, hero.h);

  ctx.fillStyle = isActive ? '#ffffff' : 'rgba(255,255,255,0.45)';
  ctx.fillRect(hero.x + 2, hero.y - 10, hero.w - 4, 6);

  if (isActive) {
    ctx.strokeStyle = 'rgba(103,232,249,0.9)';
    ctx.lineWidth = 2;
    ctx.strokeRect(hero.x - 8, hero.y - 8, hero.w + 16, hero.h + 16);
  }
}

function drawHUDLabels() {
  const hero = getActiveHero();
  ctx.fillStyle = 'rgba(15,23,42,0.8)';
  ctx.fillRect(16, 16, 240, 72);
  ctx.strokeStyle = 'rgba(255,255,255,0.2)';
  ctx.strokeRect(16, 16, 240, 72);

  ctx.font = 'bold 20px sans-serif';
  ctx.fillStyle = '#e2e8f0';
  ctx.fillText(hero.name, 30, 42);

  ctx.font = '14px sans-serif';
  ctx.fillStyle = '#cbd5e1';
  ctx.fillText(`Ability: ${hero.ability}`, 30, 64);

  ctx.fillText(`Trust: ${Math.round(trust)}%`, 30, 82);
}

function render() {
  drawBackground();
  drawPlatforms();

  for (let i = 0; i < heroes.length; i++) {
    drawHero(heroes[i], i === activeHeroIndex);
  }

  drawHUDLabels();
}

function loop() {
  handleInput();
  updatePhysics();
  updateTrustUI();
  render();
  requestAnimationFrame(loop);
}

document.addEventListener('keydown', (event) => {
  const key = event.key.toLowerCase();
  if (key === 'a' || key === 'arrowleft') keys.left = true;
  if (key === 'd' || key === 'arrowright') keys.right = true;
  if (key === 'w' || key === 'arrowup' || key === ' ') keys.jump = true;
  if (key === 'f') keys.attack = true;
  if (key === 'p') togglePhone();
  if (key === '1') switchHero(0);
  if (key === '2') switchHero(1);
  if (key === '3') switchHero(2);
});

document.addEventListener('keyup', (event) => {
  const key = event.key.toLowerCase();
  if (key === 'a' || key === 'arrowleft') keys.left = false;
  if (key === 'd' || key === 'arrowright') keys.right = false;
  if (key === 'w' || key === 'arrowup' || key === ' ') keys.jump = false;
  if (key === 'f') keys.attack = false;
});

heroButtons.forEach((btn) => {
  btn.addEventListener('click', () => {
    switchHero(Number(btn.dataset.hero));
  });
});

updateTrustUI();
requestAnimationFrame(loop);
```

