const canvas = document.getElementById("gameCanvas");
const ctx = canvas.getContext("2d");

const statusEl = document.getElementById("status");
const trustFill = document.getElementById("trustFill");
const phoneOverlay = document.getElementById("phoneOverlay");
const phoneClose = document.getElementById("phoneClose");

const keys = {};
const heroNames = ["Blackhujus", "Mr. PING", "Merhujus"];
const heroColors = ["#ff7d5c", "#7ae7ff", "#a5ff9c"];

const world = {
  width: canvas.width,
  height: canvas.height,
  walls: [
    { x: 120, y: 110, w: 300, h: 18 },
    { x: 280, y: 200, w: 18, h: 220 },
    { x: 520, y: 150, w: 18, h: 260 },
    { x: 170, y: 420, w: 360, h: 18 },
    { x: 680, y: 110, w: 18, h: 330 },
  ],
  switches: [
    { x: 230, y: 80, id: "A", active: false },
    { x: 620, y: 420, id: "B", active: false },
    { x: 820, y: 180, id: "C", active: false },
  ],
  exit: { x: 860, y: 500, w: 50, h: 50 },
  loot: [
    { x: 200, y: 300, picked: false },
    { x: 760, y: 250, picked: false },
    { x: 610, y: 120, picked: false }
  ],
  truck: { x: 800, y: 320, w: 90, h: 40 }
};

let trust = 65;
let selectedHero = 0;
let gameWon = false;

const heroData = [
  { name: "Blackhujus", x: 80, y: 180, r: 14, color: heroColors[0], speed: 2.2, role: "Tank" },
  { name: "Mr. PING", x: 80, y: 250, r: 12, color: heroColors[1], speed: 2.7, role: "Rogue" },
  { name: "Merhujus", x: 80, y: 320, r: 13, color: heroColors[2], speed: 2.4, role: "Engineer" }
];

function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

function setStatus(message) {
  statusEl.textContent = "Mission: " + message;
}

function updateTrustBar() {
  trustFill.style.width = trust + "%";
}

function togglePhone() {
  phoneOverlay.classList.toggle("hidden");
}

function rectsIntersect(a, b) {
  return a.x < b.x + b.w &&
         a.x + a.w > b.x &&
         a.y < b.y + b.h &&
         a.y + a.h > b.y;
}

function circleRectCollision(circle, rect) {
  const closestX = clamp(circle.x, rect.x, rect.x + rect.w);
  const closestY = clamp(circle.y, rect.y, rect.y + rect.h);
  const dx = circle.x - closestX;
  const dy = circle.y - closestY;
  return (dx * dx + dy * dy) < circle.r * circle.r;
}

function moveHero(hero, dx, dy) {
  const nextX = hero.x + dx;
  const nextY = hero.y + dy;

  const test = { x: nextX - hero.r, y: nextY - hero.r, w: hero.r * 2, h: hero.r * 2 };

  let canMove = true;
  for (const wall of world.walls) {
    if (rectsIntersect(test, wall)) {
      canMove = false;
      break;
    }
  }

  if (canMove) {
    hero.x = clamp(nextX, 20, canvas.width - 20);
    hero.y = clamp(nextY, 20, canvas.height - 20);
  } else {
    trust = clamp(trust - 1, 0, 100);
    updateTrustBar();
  }
}

function interact() {
  const hero = heroData[selectedHero];
  const interactRadius = 26;

  for (const s of world.switches) {
    if (Math.hypot(hero.x - s.x, hero.y - s.y) < interactRadius) {
      s.active = true;
      setStatus("Switch activated: " + s.id);
      return;
    }
  }

  const truckZone = {
    x: world.truck.x - 18,
    y: world.truck.y - 18,
    w: world.truck.w + 36,
    h: world.truck.h + 36
  };

  if (rectsIntersect(
    { x: hero.x - hero.r, y: hero.y - hero.r, w: hero.r*2, h: hero.r*2 },
    truckZone
  )) {
    setStatus("Merhujus' truck is ready. Team movement is synced.");
    return;
  }

  for (const loot of world.loot) {
    if (!loot.picked && Math.hypot(hero.x - loot.x, hero.y - loot.y) < 20) {
      loot.picked = true;
      trust = clamp(trust - 8, 0, 100);
      setStatus(hero.name + " took the loot selfishly. Trust dropped.");
      updateTrustBar();
      return;
    }
  }

  const exitRect = world.exit;
  if (circleRectCollision({ x: hero.x, y: hero.y, r: hero.r }, exitRect)) {
    const allSwitches = world.switches.every(s => s.active);

    if (allSwitches) {
      gameWon = true;
      setStatus("Temple unlocked. Criminal empire secured.");
    } else {
      setStatus("Need all three temple switches to unlock the exit.");
    }
  }
}

document.addEventListener("keydown", (e) => {
  keys[e.key.toLowerCase()] = true;

  if (e.key === "1") selectedHero = 0;
  if (e.key === "2") selectedHero = 1;
  if (e.key === "3") selectedHero = 2;

  if (e.key.toLowerCase() === "e") {
    interact();
  }

  if (e.key.toLowerCase() === "t") {
    togglePhone();
  }

  if (e.key.toLowerCase() === " ") {
    if (!gameWon) {
      trust = clamp(trust + 5, 0, 100);
      setStatus("Team sync boost: trust increased.");
      updateTrustBar();
    }
  }
});

document.addEventListener("keyup", (e) => {
  keys[e.key.toLowerCase()] = false;
});

phoneClose.addEventListener("click", togglePhone);

function update() {
  if (gameWon) return;

  const hero = heroData[selectedHero];
  let dx = 0;
  let dy = 0;

  if (keys["w"] || keys["arrowup"]) dy -= hero.speed;
  if (keys["s"] || keys["arrowdown"]) dy += hero.speed;
  if (keys["a"] || keys["arrowleft"]) dx -= hero.speed;
  if (keys["d"] || keys["arrowright"]) dx += hero.speed;

  if (dx !== 0 || dy !== 0) {
    moveHero(hero, dx, dy);
  }

  // If the selected hero is on the truck, allow team movement boost
  const truckZone = { x: world.truck.x, y: world.truck.y, w: world.truck.w, h: world.truck.h };
  if (circleRectCollision({ x: hero.x, y: hero.y, r: hero.r }, truckZone)) {
    trust = clamp(trust + 0.12, 0, 100);
    updateTrustBar();
  }

  if (world.switches.every(s => s.active)) {
    setStatus("All temple switches are active. Escape is open!");
  } else {
    const active = world.switches.filter(s => s.active).length;
    setStatus("Temple locks: " + active + "/3 active");
  }

  // Simple co-op trust reward if all heroes are close
  const closeEnough = heroData.every((h) => Math.hypot(h.x - hero.x, h.y - hero.y) < 120);
  if (closeEnough && trust < 100) {
    trust = clamp(trust + 0.04, 0, 100);
    updateTrustBar();
  }
}

function drawSwitch(s) {
  ctx.fillStyle = s.active ? "#5ef7a3" : "#ff7b7b";
  ctx.beginPath();
  ctx.arc(s.x, s.y, 10, 0, Math.PI * 2);
  ctx.fill();

  ctx.strokeStyle = "rgba(255,255,255,0.5)";
  ctx.beginPath();
  ctx.arc(s.x, s.y, 16, 0, Math.PI * 2);
  ctx.stroke();
}

function drawTruck() {
  const { x, y, w, h } = world.truck;
  ctx.fillStyle = "#d1b67d";
  ctx.fillRect(x, y, w, h);
  ctx.fillStyle = "#4a3f2f";
  ctx.fillRect(x + 18, y + 8, 20, 12);
  ctx.fillRect(x + 50, y + 8, 20, 12);
  ctx.fillStyle = "#2f2b2a";
  ctx.fillRect(x + 28, y + 26, 28, 8);
}

function drawLoot() {
  for (const loot of world.loot) {
    if (loot.picked) continue;
    ctx.fillStyle = "#f6d365";
    ctx.beginPath();
    ctx.arc(loot.x, loot.y, 8, 0, Math.PI * 2);
    ctx.fill();
  }
}

function drawExit() {
  const { x, y, w, h } = world.exit;
  ctx.strokeStyle = "#7ae7ff";
  ctx.lineWidth = 3;
  ctx.strokeRect(x, y, w, h);
}

function drawWalls() {
  ctx.fillStyle = "#2d3e53";
  for (const wall of world.walls) {
    ctx.fillRect(wall.x, wall.y, wall.w, wall.h);
  }
}

function drawHeroes() {
  heroData.forEach((hero, index) => {
    ctx.fillStyle = hero.color;
    ctx.beginPath();
    ctx.arc(hero.x, hero.y, hero.r, 0, Math.PI * 2);
    ctx.fill();

    if (index === selectedHero) {
      ctx.strokeStyle = "#fff4ad";
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(hero.x, hero.y, hero.r + 6, 0, Math.PI * 2);
      ctx.stroke();
    }

    ctx.fillStyle = "#ecf4ff";
    ctx.font = "12px Arial";
    ctx.fillText(hero.name.split(" ")[0], hero.x - 18, hero.y - 18);
  });
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // floor
  ctx.fillStyle = "#0e1721";
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // subtle grid
  ctx.strokeStyle = "rgba(255,255,255,0.04)";
  ctx.lineWidth = 1;
  for (let x = 0; x <= canvas.width; x += 40) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, canvas.height);
    ctx.stroke();
  }
  for (let y = 0; y <= canvas.height; y += 40) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(canvas.width, y);
    ctx.stroke();
  }

  drawWalls();
  drawTruck();
  drawSwitches();
  drawLoot();
  drawExit();
  drawHeroes();

  if (gameWon) {
    ctx.fillStyle = "rgba(0,0,0,0.45)";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = "#f4f9ff";
    ctx.font = "bold 38px Arial";
    ctx.fillText("TEMPLE SECURED", 280, 290);
    ctx.font = "20px Arial";
    ctx.fillText("The trust protocol holds. Mission complete.", 250, 330);
  }
}

function drawSwitches() {
  for (const s of world.switches) {
    drawSwitch(s);
  }
}

function loop() {
  update();
  draw();
  requestAnimationFrame(loop);
}

updateTrustBar();
setStatus("Reach the temple exit and activate all switches.");
requestAnimationFrame(loop);

