function buildHeroTabs() {
  heroTabs.innerHTML = '';
  Object.entries(HERO_DEFS).forEach(([key, hero]) => {
    const button = document.createElement('button');
    button.className = 'hero-tab' + (gameState.selectedHero === key ? ' active' : '');
    button.innerHTML = `
      <span><span class="hero-dot" style="background:${hero.color};"></span> ${hero.name}</span>
      <small>${hero.description}</small>
    `;
    button.addEventListener('click', () => {
      gameState.selectedHero = key;
      updateHeroTabs();
    });
    heroTabs.appendChild(button);
  });
}

function updateHeroTabs() {
  const tabs = heroTabs.querySelectorAll('.hero-tab');
  tabs.forEach((tab, index) => {
    const key = Object.keys(HERO_DEFS)[index];
    tab.classList.toggle('active', gameState.selectedHero === key);
  });
}

function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

function distance(a, b) {
  return Math.hypot(a.x - b.x, a.y - b.y);
}

function addToast(text) {
  toast.textContent = text;
  toast.classList.remove('hidden');
  clearTimeout(addToast.timer);
  addToast.timer = setTimeout(() => toast.classList.add('hidden'), 1600);
}

function resetRelics() {
  gameState.relics = world.relicPositions.map((p) => ({ ...p, collected: false, pulse: 0 }));
}

function spawnEnemy() {
  const side = Math.floor(Math.random() * 4);
  let x = 0;
  let y = 0;
  if (side === 0) { x = Math.random() * world.width; y = -20; }
  if (side === 1) { x = world.width + 20; y = Math.random() * world.height; }
  if (side === 2) { x = Math.random() * world.width; y = world.height + 20; }
  if (side === 3) { x = -20; y = Math.random() * world.height; }

  const target = heroes[gameState.selectedHero];
  gameState.enemies.push({
    x,
    y,
    radius: 16,
    hp: 55 + gameState.wave * 8,
    maxHp: 55 + gameState.wave * 8,
    speed: 40 + gameState.wave * 7,
    color: '#ff6b73',
    meleeCooldown: 0,
    hitFlash: 0,
    targetX: target.x,
    targetY: target.y,
  });
}

function init() {
  buildHeroTabs();
  resetRelics();
  updateObjective();
  phonePanel.classList.add('hidden');
  addToast('Mission loaded: secure the relics.');
}

function canUseHeroAbility(heroKey, abilityKey) {
  const hero = heroes[heroKey];
  if (!hero) return false;
  if (hero.hp <= 0) return false;
  if (gameState.trust < 30 && abilityKey !== 'primary') return false;
  return hero.cooldowns[abilityKey] <= 0;
}

function applyAbility(key) {
  const hero = heroes[gameState.selectedHero];
  if (!hero || hero.hp <= 0) return;

  const ability = key === 'primary' ? 'primary' : 'secondary';
  if (!canUseHeroAbility(gameState.selectedHero, ability)) return;

  hero.cooldowns[ability] = ability === 'primary' ? 0.7 : 2.2;

  if (gameState.selectedHero === 'blackhujus') {
    if (ability === 'primary') {
      const range = 100;
      damageNearbyEnemies(hero, 42, range, 70);
      gameState.trust = clamp(gameState.trust - 2, 0, 100);
      addToast('Blackhujus unleashes a heavy slam.');
    } else {
      hero.hp = clamp(hero.hp + 18, 0, hero.maxHp);
      gameState.trust = clamp(gameState.trust - 4, 0, 100);
      addToast('Blackhujus absorbs damage and tanks the lane.');
    }
  }

  if (gameState.selectedHero === 'ping') {
    if (ability === 'primary') {
      hero.x += hero.facing.x * 28;
      hero.y += hero.facing.y * 28;
      damageNearbyEnemies(hero, 28, 90, 40);
      gameState.trust = clamp(gameState.trust - 3, 0, 100);
      addToast('Mr. PING blurs through the room.');
    } else {
      gameState.projectiles.push({
        x: hero.x,
        y: hero.y,
        radius: 8,
        dx: hero.facing.x * 7,
        dy: hero.facing.y * 7,
        ttl: 1.1,
        color: '#69e3ff'
      });
      gameState.trust = clamp(gameState.trust - 5, 0, 100);
      addToast('Grapple pulse snaps across the map.');
    }
  }

  if (gameState.selectedHero === 'merhujus') {
    if (ability === 'primary') {
      for (const teamHero of Object.values(heroes)) {
        teamHero.hp = clamp(teamHero.hp + 12, 0, teamHero.maxHp);
      }
      gameState.trust = clamp(gameState.trust - 2, 0, 100);
      addToast('Merhujus repairs the squad.');
    } else {
      const target = getNearestEnemy(hero.x, hero.y, 160);
      if (target) {
        target.hp -= 30;
        target.hitFlash = 0.15;
      }
      gameState.trust = clamp(gameState.trust - 4, 0, 100);
      addToast('Merhujus fires a support pulse.');
    }
  }
}

function damageNearbyEnemies(hero, damage, range, force) {
  for (const enemy of gameState.enemies) {
    const dist = distance(hero, enemy);
    if (dist < range) {
      enemy.hp -= damage;
      enemy.hitFlash = 0.18;
      const angle = Math.atan2(enemy.y - hero.y, enemy.x - hero.x);
      enemy.x += Math.cos(angle) * force;
      enemy.y += Math.sin(angle) * force;
    }
  }
}

function getNearestEnemy(x, y, radius) {
  let nearest = null;
  let best = radius;
  for (const enemy of gameState.enemies) {
    const d = Math.hypot(enemy.x - x, enemy.y - y);
    if (d < best) {
      best = d;
      nearest = enemy;
    }
  }
  return nearest;
}

function updateObjective() {
  const collected = gameState.relics.filter(r => r.collected).length;
  relicCount.textContent = `${collected} / 3`;
  enemyCount.textContent = String(gameState.enemies.length);
  trustFill.style.width = `${gameState.trust}%`;
  trustValue.textContent = `${Math.round(gameState.trust)}%`;

  if (gameState.victory) {
    objectiveText.textContent = 'Mission complete: the team secured the prototype win.';
    phoneMission.textContent = 'Objective complete. Safehouse restored and challenge resolved.';
    return;
  }

  if (gameState.missionStage === 'relics') {
    objectiveText.textContent = 'Secure the relics and access the Banana Temple gate.';
    phoneMission.textContent = 'Locate relic caches and stabilize the local trust network.';
  } else if (gameState.gateOpen) {
    objectiveText.textContent = 'Defend the team and hold the temple gate.';
    phoneMission.textContent = 'Temple gate unlocked. Hold the perimeter until the route is secure.';
  } else {
    objectiveText.textContent = 'Temple gate is sealed. Clear the gang and recover the final relic.';
    phoneMission.textContent = 'Trust is dropping. Clear the gang and push for the gate.';
  }
}

function collectRelics() {
  for (const relic of gameState.relics) {
    if (!relic.collected) {
      const p = heroes[gameState.selectedHero];
      if (distance(relic, p) < 30) {
        relic.collected = true;
        gameState.trust = clamp(gameState.trust + 7, 0, 100);
        addToast('Relic recovered. Trust restored.');
      }
    }
  }

  if (gameState.relics.every(r => r.collected)) {
    gameState.missionStage = 'gate';
    gameState.gateOpen = true;
    addToast('Banana Temple gate unlocked.');
  }
}

function movePlayer(dt) {
  const hero = heroes[gameState.selectedHero];
  if (!hero || hero.hp <= 0) return;

  let dx = 0;
  let dy = 0;
  if (keys['KeyW'] || keys['ArrowUp']) dy -= 1;
  if (keys['KeyS'] || keys['ArrowDown']) dy += 1;
  if (keys['KeyA'] || keys['ArrowLeft']) dx -= 1;
  if (keys['KeyD'] || keys['ArrowRight']) dx += 1;

  if (dx || dy) {
    const mag = Math.hypot(dx, dy) || 1;
    dx /= mag;
    dy /= mag;
    hero.x += dx * hero.speed * dt;
    hero.y += dy * hero.speed * dt;
    hero.facing.x = dx;
    hero.facing.y = dy;
  }

  hero.x = clamp(hero.x, 40, world.width - 40);
  hero.y = clamp(hero.y, 40, world.height - 40);

  if (gameState.activePhone) {
    hero.x = clamp(hero.x, 20, world.width - 20);
    hero.y = clamp(hero.y, 20, world.height - 20);
  }
}

function enemiesToHero(dt) {
  for (const enemy of gameState.enemies) {
    const hero = heroes[gameState.selectedHero];
    if (!hero) continue;
    const angle = Math.atan2(hero.y - enemy.y, hero.x - enemy.x);
    const dist = Math.hypot(hero.x - enemy.x, hero.y - enemy.y);
    if (dist > 2) {
      enemy.x += Math.cos(angle) * enemy.speed * dt;
      enemy.y += Math.sin(angle) * enemy.speed * dt;
    }

    if (dist < enemy.radius + hero.radius + 10 && enemy.meleeCooldown <= 0) {
      hero.hp -= 12;
      enemy.meleeCooldown = 0.8;
      gameState.trust = clamp(gameState.trust - 3, 0, 100);
      if (hero.hp <= 0) {
        hero.hp = 0;
        addToast(`${hero.name} has fallen. Switch teams and regroup.`);
      }
    }

    enemy.meleeCooldown -= dt;
    enemy.hitFlash = Math.max(0, enemy.hitFlash - dt);
  }
}

function updateProjectiles(dt) {
  for (const proj of gameState.projectiles) {
    proj.x += proj.dx;
    proj.y += proj.dy;
    proj.ttl -= dt;

    for (const enemy of gameState.enemies) {
      if (distance(proj, enemy) < proj.radius + enemy.radius) {
        enemy.hp -= 20;
        enemy.hitFlash = 0.2;
        proj.ttl = 0;
      }
    }
  }

  gameState.projectiles = gameState.projectiles.filter(p => p.ttl > 0);
}

function updateParticles(dt) {
  for (const p of gameState.particles) {
    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.life -= dt;
  }
  gameState.particles = gameState.particles.filter(p => p.life > 0);
}

function updateCooldowns(dt) {
  for (const hero of Object.values(heroes)) {
    hero.cooldowns.primary = Math.max(0, hero.cooldowns.primary - dt);
    hero.cooldowns.secondary = Math.max(0, hero.cooldowns.secondary - dt);
  }
}

function maybeSpawnEnemy(dt) {
  if (gameState.gateOpen && gameState.enemies.length < 10) {
    gameState.lastSpawn += dt;
    if (gameState.lastSpawn >= 2.4) {
      gameState.lastSpawn = 0;
      spawnEnemy();
    }
  }
}

function cleanupDefeatedEnemies() {
  const survivors = [];
  for (const enemy of gameState.enemies) {
    if (enemy.hp > 0) {
      survivors.push(enemy);
    } else {
      for (let i = 0; i < 10; i++) {
        gameState.particles.push({
          x: enemy.x,
          y: enemy.y,
          vx: (Math.random() - 0.5) * 120,
          vy: (Math.random() - 0.5) * 120,
          life: 0.5,
          color: '#ffcf66',
          size: 2 + Math.random() * 3,
        });
      }
      gameState.trust = clamp(gameState.trust + 2, 0, 100);
    }
  }
  gameState.enemies = survivors;
}

function checkVictory() {
  if (gameState.relics.every(r => r.collected) && gameState.enemies.length === 0 && gameState.gateOpen) {
    if (distance(heroes[gameState.selectedHero], world.templeGate) < 110) {
      gameState.victory = true;
      addToast('Banana Temple secured. Trust Protocol mission complete.');
    }
  }
}

function update(dt) {
  if (gameState.victory || gameState.defeat) return;

  gameState.time += dt;
  gameState.trust = clamp(gameState.trust + dt * 0.25, 0, 100);

  if (gameState.trust <= 0) {
    gameState.defeat = true;
    addToast('Trust collapsed. The squad must regroup.');
  }

  movePlayer(dt);
  collectRelics();
  enemiesToHero(dt);
  updateProjectiles(dt);
  updateParticles(dt);
  updateCooldowns(dt);
  maybeSpawnEnemy(dt);
  cleanupDefeatedEnemies();

  if (gameState.gateOpen) {
    gameState.gateGlow += dt * 6;
  }

  checkVictory();
  updateObjective();
}

function drawWorld() {
  ctx.clearRect(0, 0, world.width, world.height);

  const sky = ctx.createLinearGradient(0, 0, 0, world.height);
  sky.addColorStop(0, '#0f1d28');
  sky.addColorStop(1, '#0a1115');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, world.width, world.height);

  ctx.fillStyle = '#132833';
  for (let x = 0; x < world.width; x += 32) {
    ctx.fillRect(x, 0, 1, world.height);
  }
  for (let y = 0; y < world.height; y += 32) {
    ctx.fillRect(0, y, world.width, 1);
  }

  for (const b of world.buildings) {
    ctx.fillStyle = '#132b35';
    ctx.fillRect(b.x, b.y, b.w, b.h);
    ctx.fillStyle = 'rgba(91, 229, 255, 0.12)';
    ctx.fillRect(b.x + 10, b.y + 10, b.w - 20, b.h - 20);
  }

  ctx.fillStyle = '#0f1a20';
  ctx.fillRect(1060, 200, 100, 160);

  if (gameState.gateOpen) {
    ctx.fillStyle = '#8ef7b1';
    ctx.shadowBlur = 18;
    ctx.shadowColor = '#8ef7b1';
    ctx.fillRect(1095, 205, 30, 150);
    ctx.shadowBlur = 0;
  } else {
    ctx.fillStyle = '#ff9b7c';
    ctx.fillRect(1095, 205, 30, 150);
  }

  ctx.fillStyle = '#1a2d34';
  ctx.fillRect(1000, 170, 220, 20);
  ctx.fillRect(1000, 360, 220, 20);

  for (const relic of gameState.relics) {
    if (relic.collected) continue;
    ctx.save();
    const pulse = 1 + Math.sin(gameState.time * 5 + relic.x) * 0.2;
    ctx.translate(relic.x, relic.y);
    ctx.scale(pulse, pulse);
    ctx.fillStyle = '#ffd36d';
    ctx.beginPath();
    ctx.moveTo(0, -10);
    ctx.lineTo(8, 0);
    ctx.lineTo(0, 10);
    ctx.lineTo(-8, 0);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }
}

function drawPlayers() {
  for (const heroKey of Object.keys(HERO_DEFS)) {
    const hero = heroes[heroKey];
    if (!hero) continue;

    const isSelected = heroKey === gameState.selectedHero;
    ctx.save();
    ctx.translate(hero.x, hero.y);

    ctx.fillStyle = hero.color;
    ctx.beginPath();
    ctx.arc(0, 0, hero.radius, 0, Math.PI * 2);
    ctx.fill();

    ctx.strokeStyle = isSelected ? '#ffffff' : 'rgba(255,255,255,0.3)';
    ctx.lineWidth = 3;
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(hero.facing.x * 18, hero.facing.y * 18);
    ctx.strokeStyle = hero.accent;
    ctx.lineWidth = 3;
    ctx.stroke();

    ctx.fillStyle = 'rgba(0,0,0,0.28)';
    ctx.fillRect(-16, -28, 32, 5);
    ctx.fillStyle = '#8ef7b1';
    ctx.fillRect(-16, -28, 32 * (hero.hp / hero.maxHp), 5);

    ctx.restore();
  }
}

function drawEnemies() {
  for (const enemy of gameState.enemies) {
    ctx.save();
    ctx.translate(enemy.x, enemy.y);
    if (enemy.hitFlash > 0) {
      ctx.fillStyle = '#fff7b3';
    } else {
      ctx.fillStyle = enemy.color;
    }
    ctx.beginPath();
    ctx.arc(0, 0, enemy.radius, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = 'rgba(0,0,0,0.2)';
    ctx.fillRect(-12, -20, 24, 4);
    ctx.fillStyle = '#ff8f6c';
    ctx.fillRect(-12, -20, 24 * (enemy.hp / enemy.maxHp), 4);
    ctx.restore();
  }
}

function drawProjectiles() {
  for (const p of gameState.projectiles) {
    ctx.fillStyle = p.color;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
    ctx.fill();
  }
}

function drawParticles() {
  for (const p of gameState.particles) {
    ctx.fillStyle = p.color;
    ctx.fillRect(p.x, p.y, p.size, p.size);
  }
}

function drawUI() {
  if (gameState.victory) {
    ctx.fillStyle = 'rgba(4, 9, 12, 0.6)';
    ctx.fillRect(0, 0, world.width, world.height);
    ctx.fillStyle = '#edf7ff';
    ctx.textAlign = 'center';
    ctx.font = 'bold 48px sans-serif';
    ctx.fillText('Mission Complete', world.width / 2, world.height / 2 - 20);
    ctx.font = '24px sans-serif';
    ctx.fillText('Trust Protocol restored.', world.width / 2, world.height / 2 + 30);
  }
}

function render() {
  drawWorld();
  drawProjectiles();
  drawParticles();
  drawEnemies();
  drawPlayers();
  drawUI();
}

function gameLoop() {
  const now = performance.now();
  const dt = Math.min((now - (gameLoop.last || now)) / 1000, 0.033);
  gameLoop.last = now;

  update(dt);
  render();
  requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (event) => {
  keys[event.code] = true;

  if (event.code === 'Digit1') gameState.selectedHero = 'blackhujus';
  if (event.code === 'Digit2') gameState.selectedHero = 'ping';
  if (event.code === 'Digit3') gameState.selectedHero = 'merhujus';

  if (event.code === 'KeyQ') applyAbility('primary');
  if (event.code === 'KeyE') applyAbility('secondary');
  if (event.code === 'KeyF') {
    for (const hero of Object.values(heroes)) {
      hero.hp = clamp(hero.hp + 8, 0, hero.maxHp);
    }
    gameState.trust = clamp(gameState.trust - 1, 0, 100);
    addToast('Team support pulse synced.');
  }
  if (event.code === 'KeyT') {
    gameState.activePhone = !gameState.activePhone;
    phonePanel.classList.toggle('hidden', !gameState.activePhone);
  }
  if (event.code === 'Space') {
    const hero = heroes[gameState.selectedHero];
    if (!hero) return;
    damageNearbyEnemies(hero, hero.attack, 54, 25);
  }

  updateHeroTabs();
});

document.addEventListener('keyup', (event) => {
  keys[event.code] = false;
});

init();
requestAnimationFrame(gameLoop);

const canvas = document.getElementById("gameCanvas");
const ctx = canvas.getContext("2d");

const trustFill = document.getElementById("trustFill");
const trustValue = document.getElementById("trustValue");
const missionText = document.getElementById("missionText");
const teamList = document.getElementById("teamList");

const input = {
  keyMap: new Map(),
};

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function rectsOverlap(a, b) {
  return (
    a.x < b.x + b.w &&
    a.x + a.w > b.x &&
    a.y < b.y + b.h &&
    a.y + a.h > b.y
  );
}

class Hero {
  constructor({ name, color, x, y, controls, accent }) {
    this.name = name;
    this.color = color;
    this.accent = accent;
    this.x = x;
    this.y = y;
    this.w = 20;
    this.h = 20;
    this.speed = 96;
    this.controls = controls;
    this.active = true;
    this.artifactCount = 0;
    this.isBoosting = false;
  }

  move(dx, dy, obstacles) {
    const nextX = this.x + dx;
    const nextY = this.y + dy;

    const candidateX = { x: nextX, y: this.y, w: this.w, h: this.h };
    const collidesX = obstacles.some((wall) => rectsOverlap(candidateX, wall));
    if (!collidesX) this.x = nextX;

    const candidateY = { x: this.x, y: nextY, w: this.w, h: this.h };
    const collidesY = obstacles.some((wall) => rectsOverlap(candidateY, wall));
    if (!collidesY) this.y = nextY;

    this.x = clamp(this.x, 0, canvas.width - this.w);
    this.y = clamp(this.y, 0, canvas.height - this.h);
  }

  update(dt, world, game) {
    const dx =
      Number(input.keyMap.get(this.controls.right) ?? 0) -
      Number(input.keyMap.get(this.controls.left) ?? 0);

    const dy =
      Number(input.keyMap.get(this.controls.down) ?? 0) -
      Number(input.keyMap.get(this.controls.up) ?? 0);

    const boost = input.keyMap.get("Space") ? 1.6 : 1;
    const moveX = dx * this.speed * boost * dt;
    const moveY = dy * this.speed * boost * dt;

    this.move(moveX, moveY, world.obstacles);

    if (input.keyMap.get("Space") && (Math.abs(moveX) > 0 || Math.abs(moveY) > 0)) {
      game.trust = clamp(game.trust - 0.4, 0, 100);
      this.isBoosting = true;
    } else {
      this.isBoosting = false;
    }

    for (const relic of world.relics) {
      if (!relic.collected && rectsOverlap({ x: this.x, y: this.y, w: this.w, h: this.h }, relic.hitbox)) {
        relic.collected = true;
        this.artifactCount += 1;
        game.trust = clamp(game.trust + 8, 0, 100);
      }
    }

    for (const switchTile of world.switches) {
      if (rectsOverlap({ x: this.x, y: this.y, w: this.w, h: this.h }, switchTile.hitbox)) {
        switchTile.activatedBy = this.name;
      }
    }

    if (rectsOverlap({ x: this.x, y: this.y, w: this.w, h: this.h }, world.exit)) {
      game.victory = world.relics.every((relic) => relic.collected);
    }
  }

  draw() {
    ctx.fillStyle = this.color;
    ctx.fillRect(this.x, this.y, this.w, this.h);

    ctx.fillStyle = this.accent;
    ctx.fillRect(this.x + 6, this.y + 6, 8, 8);

    ctx.fillStyle = "rgba(255,255,255,0.3)";
    ctx.fillRect(this.x + 2, this.y + 16, 16, 3);
  }
}

class World {
  constructor() {
    this.obstacles = [
      { x: 0, y: 0, w: canvas.width, h: 32 },
      { x: 0, y: 0, w: 32, h: canvas.height },
      { x: 0, y: canvas.height - 32, w: canvas.width, h: 32 },
      { x: canvas.width - 32, y: 0, w: 32, h: canvas.height },

      { x: 160, y: 120, w: 200, h: 26 },
      { x: 540, y: 120, w: 200, h: 26 },
      { x: 160, y: 360, w: 220, h: 26 },
      { x: 560, y: 360, w: 170, h: 26 },
      { x: 440, y: 160, w: 26, h: 180 },
      { x: 300, y: 250, w: 26, h: 150 },
    ];

    this.exit = { x: 810, y: 76, w: 56, h: 54 };

    this.relics = [
      { id: "golden-machete", x: 100, y: 180, w: 18, h: 18, collected: false, color: "#ffd166" },
      { id: "grappling-hook", x: 740, y: 420, w: 18, h: 18, collected: false, color: "#7bdff2" },
      { id: "timeline-device", x: 510, y: 210, w: 18, h: 18, collected: false, color: "#ff8fab" }
    ].map((relic) => ({ ...relic, hitbox: { x: relic.x, y: relic.y, w: relic.w, h: relic.h } }));

    this.switches = [
      { id: "switch-a", x: 86, y: 440, w: 18, h: 18, activatedBy: null, hitbox: { x: 86, y: 440, w: 18, h: 18 } },
      { id: "switch-b", x: 438, y: 88, w: 18, h: 18, activatedBy: null, hitbox: { x: 438, y: 88, w: 18, h: 18 } },
      { id: "switch-c", x: 786, y: 270, w: 18, h: 18, activatedBy: null, hitbox: { x: 786, y: 270, w: 18, h: 18 } },
    ];
  }

  drawFloor() {
    ctx.fillStyle = "#162437";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    for (let y = 0; y < canvas.height; y += 32) {
      for (let x = 0; x < canvas.width; x += 32) {
        ctx.fillStyle = (x + y) % 64 === 0 ? "#1c2d44" : "#13243a";
        ctx.fillRect(x, y, 32, 32);
      }
    }
  }

  drawExit() {
    ctx.fillStyle = "#ffd166";
    ctx.fillRect(this.exit.x, this.exit.y, this.exit.w, this.exit.h);
    ctx.fillStyle = "#1b1f2d";
    ctx.fillRect(this.exit.x + 10, this.exit.y + 12, this.exit.w - 20, this.exit.h - 20);
  }

  drawRelics() {
    for (const relic of this.relics) {
      if (relic.collected) continue;
      ctx.fillStyle = relic.color;
      ctx.fillRect(relic.x, relic.y, relic.w, relic.h);
      ctx.fillStyle = "#0d1120";
      ctx.fillRect(relic.x + 5, relic.y + 5, 8, 8);
    }
  }

  drawSwitches() {
    for (const switchTile of this.switches) {
      ctx.fillStyle = switchTile.activatedBy ? "#70f0a7" : "#ff706f";
      ctx.fillRect(switchTile.x, switchTile.y, switchTile.w, switchTile.h);
      ctx.fillStyle = "#0b1020";
      ctx.fillRect(switchTile.x + 4, switchTile.y + 4, 10, 10);
    }
  }

  drawObstacles() {
    for (const wall of this.obstacles) {
      ctx.fillStyle = "#6c7da8";
      ctx.fillRect(wall.x, wall.y, wall.w, wall.h);
      ctx.fillStyle = "#4f5d8a";
      ctx.fillRect(wall.x + 4, wall.y + 4, wall.w - 8, wall.h - 8);
    }
  }
}

class Game {
  constructor() {
    this.world = new World();
    this.heroes = [
      new Hero({
        name: "Blackhujus",
        color: "#ff8d6b",
        accent: "#ffc88b",
        x: 84,
        y: 72,
        controls: { up: "KeyW", down: "KeyS", left: "KeyA", right: "KeyD" },
      }),
      new Hero({
        name: "Mr. PING",
        color: "#7bdff2",
        accent: "#dff9ff",
        x: 110,
        y: 78,
        controls: { up: "KeyI", down: "KeyK", left: "KeyJ", right: "KeyL" },
      }),
      new Hero({
        name: "Merhujus",
        color: "#a6ffb2",
        accent: "#ecffe9",
        x: 136,
        y: 84,
        controls: { up: "ArrowUp", down: "ArrowDown", left: "ArrowLeft", right: "ArrowRight" },
      }),
    ];

    this.trust = 100;
    this.victory = false;
    this.phoneOpen = false;
    this.lastTime = 0;
    this.messageQueue = [
      "Mercenary channel: keep the crew together.",
      "Safe house access key ready.",
      "Loot is better shared than stolen.",
    ];
    this.messageIndex = 0;
    this.updateHud();
  }

  updateHud() {
    trustFill.style.width = `${this.trust}%`;
    trustValue.textContent = `${Math.round(this.trust)}%`;

    const teamHtml = this.heroes
      .map((hero) => {
        const status = this.world.relics.some((relic) => !relic.collected) ? "Active" : "Ready";
        return `
          <div class="team-item">
            <div class="hero-tag">
              <span class="swatch" style="background:${hero.color};"></span>
              ${hero.name}
            </div>
            <span class="status-pill">${status}</span>
          </div>
        `;
      })
      .join("");

    teamList.innerHTML = teamHtml;

    const artifactsLeft = this.world.relics.filter((relic) => !relic.collected).length;
    missionText.textContent = this.victory
      ? "The vault is open. Trust Protocol achieved."
      : artifactsLeft > 0
        ? `Recover the ${artifactsLeft} remaining artifact${artifactsLeft > 1 ? "s" : ""} and stabilize the team.`
        : "The vault is exposed. Reach the extraction point.";
  }

  togglePhone() {
    this.phoneOpen = !this.phoneOpen;
  }

  update(dt) {
    if (this.victory) {
      return;
    }

    for (const hero of this.heroes) {
      hero.update(dt, this.world, this);
    }

    const allSwitchesActive = this.world.switches.every((switchTile) => switchTile.activatedBy !== null);
    if (allSwitchesActive) {
      this.trust = clamp(this.trust + 0.22, 0, 100);
    }

    if (this.world.relics.every((relic) => relic.collected)) {
      this.trust = clamp(this.trust + 0.5, 0, 100);
    }

    if (input.keyMap.get("KeyP")) {
      this.togglePhone();
      input.keyMap.delete("KeyP");
    }

    if (input.keyMap.get("KeyT")) {
      this.messageIndex = (this.messageIndex + 1) % this.messageQueue.length;
      input.keyMap.delete("KeyT");
    }

    this.updateHud();
  }

  drawPhone() {
    if (!this.phoneOpen) return;

    ctx.fillStyle = "rgba(7, 11, 19, 0.72)";
    ctx.fillRect(160, 60, 640, 420);

    ctx.fillStyle = "#dfeaff";
    ctx.fillRect(190, 90, 580, 360);

    ctx.fillStyle = "#111827";
    ctx.fillRect(210, 110, 540, 320);

    ctx.fillStyle = "#7bdff2";
    ctx.font = "18px sans-serif";
    ctx.fillText("TRUST PROTOCOL // COMMUNICATION", 230, 150);

    ctx.fillStyle = "#ecf3ff";
    ctx.fillText("Mission feed:", 230, 190);
    ctx.fillText(this.messageQueue[this.messageIndex], 230, 220);
    ctx.fillText("Team status:", 230, 280);

    for (let i = 0; i < this.heroes.length; i += 1) {
      const hero = this.heroes[i];
      ctx.fillStyle = hero.color;
      ctx.fillRect(230 + i * 160, 300, 18, 18);
      ctx.fillStyle = "#ecf3ff";
      ctx.fillText(hero.name, 258 + i * 160, 314);
    }
  }

  draw() {
    this.world.drawFloor();
    this.world.drawObstacles();
    this.world.drawRelics();
    this.world.drawSwitches();
    this.world.drawExit();

    for (const hero of this.heroes) {
      hero.draw();
    }

    ctx.fillStyle = "rgba(255, 255, 255, 0.15)";
    ctx.fillRect(24, 24, 180, 62);
    ctx.fillStyle = "#edf2ff";
    ctx.font = "16px sans-serif";
    ctx.fillText("Artifacts:", 36, 50);
    ctx.fillText(`${this.world.relics.filter((relic) => relic.collected).length}/${this.world.relics.length}`, 36, 72);

    this.drawPhone();

    if (this.victory) {
      ctx.fillStyle = "rgba(7,11,19,0.72)";
      ctx.fillRect(180, 190, 600, 150);
      ctx.fillStyle = "#f8d76a";
      ctx.font = "bold 36px sans-serif";
      ctx.fillText("MISSION COMPLETE", 300, 255);
      ctx.font = "20px sans-serif";
      ctx.fillText("Trust Protocol restored. Cartel vault breached.", 270, 300);
    }
  }

  loop(timestamp) {
    const dt = Math.min((timestamp - this.lastTime) / 1000 || 0.016, 0.03);
    this.lastTime = timestamp;
    this.update(dt);
    this.draw();
    requestAnimationFrame((time) => this.loop(time));
  }
}

window.addEventListener("keydown", (event) => {
  input.keyMap.set(event.code, true);

  if (
    ["KeyW", "KeyA", "KeyS", "KeyD", "KeyI", "KeyJ", "KeyK", "KeyL",
     "ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight",
     "Space", "KeyP", "KeyT"].includes(event.code)
  ) {
    event.preventDefault();
  }
});

window.addEventListener("keyup", (event) => {
  input.keyMap.set(event.code, false);
});

const game = new Game();
requestAnimationFrame((time) => game.loop(time));

