import * as THREE from 'three';
import { createUI, setTrust } from './ui.js';

// Simple single-player prototype: 3 cubes are heroes; player controls the first cube.
// Left-click to fire a grappling hook from the player toward the clicked point.

export function startGame() {
  const container = document.getElementById('app');

  // Renderer
  const renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  container.appendChild(renderer.domElement);

  // Scene
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x87ceeb);

  // Camera
  const camera = new THREE.PerspectiveCamera(60, innerWidth / innerHeight, 0.1, 1000);
  camera.position.set(0, 18, 24);
  camera.lookAt(0, 0, 0);

  // Lights
  const hemi = new THREE.HemisphereLight(0xffffff, 0x444444, 0.9);
  scene.add(hemi);
  const dir = new THREE.DirectionalLight(0xffffff, 0.6);
  dir.position.set(5, 10, 7);
  scene.add(dir);

  // Floor
  const floorGeo = new THREE.PlaneGeometry(200, 200);
  const floorMat = new THREE.MeshStandardMaterial({ color: 0x2e7d32 });
  const floor = new THREE.Mesh(floorGeo, floorMat);
  floor.rotation.x = -Math.PI/2;
  floor.receiveShadow = true;
  scene.add(floor);

  // Heroes (placeholders)
  const heroes = [];
  const colors = [0x0b84ff, 0xff8c42, 0x8d3dae]; // Blue, Orange, Purple
  for (let i=0;i<3;i++){
    const g = new THREE.BoxGeometry(1.6,2,1.6);
    const m = new THREE.MeshStandardMaterial({color:colors[i]});
    const mesh = new THREE.Mesh(g,m);
    mesh.position.set(-4 + i*4, 1, 0);
    mesh.userData.role = i === 0 ? 'Mr.PING (player)' : (i===1?'Blackhujus':'Merhujus');
    scene.add(mesh);
    heroes.push(mesh);
  }

  // Player state and controls
  const player = heroes[0];
  const keys = {w:false,a:false,s:false,d:false,shift:false};
  window.addEventListener('keydown', e => { if (e.key) keys[e.key.toLowerCase()] = true });
  window.addEventListener('keyup', e => { if (e.key) keys[e.key.toLowerCase()] = false });

  // Grappling hook
  const raycaster = new THREE.Raycaster();
  const mouse = new THREE.Vector2();
  let hookTarget = null;
  let hookLine = null;
  const hookSpeed = 18;

  renderer.domElement.addEventListener('pointerdown', (ev) => {
    // compute mouse NDC
    mouse.x = (ev.clientX / innerWidth) * 2 - 1;
    mouse.y = - (ev.clientY / innerHeight) * 2 + 1;
    raycaster.setFromCamera(mouse, camera);
    const hits = raycaster.intersectObject(floor);
    if (hits.length) {
      hookTarget = hits[0].point.clone();
      if (hookLine) scene.remove(hookLine);
      const mat = new THREE.LineBasicMaterial({ color: 0xffffff });
      const geo = new THREE.BufferGeometry().setFromPoints([player.position.clone(), hookTarget.clone()]);
      hookLine = new THREE.Line(geo, mat);
      scene.add(hookLine);
    }
  });

  // Simple loot: a sphere to pick; picking alters trust
  const lootGeo = new THREE.SphereGeometry(0.6, 16, 12);
  const lootMat = new THREE.MeshStandardMaterial({ color: 0xffe066 });
  const loot = new THREE.Mesh(lootGeo, lootMat);
  loot.position.set(0, 0.6, -10);
  scene.add(loot);
  let trust = 70; // out of 100
  createUI({ onTogglePhone: () => { /* nothing for now */ } });
  setTrust(trust);

  // Resize
  window.addEventListener('resize', () => {
    camera.aspect = innerWidth / innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(innerWidth, innerHeight);
  });

  const clock = new THREE.Clock();

  function animate() {
    const dt = Math.min(clock.getDelta(), 0.05);
    // Movement: WASD
    const speed = keys.shift ? 12 : 6;
    const dirVec = new THREE.Vector3();
    if (keys.w) dirVec.z -= 1;
    if (keys.s) dirVec.z += 1;
    if (keys.a) dirVec.x -= 1;
    if (keys.d) dirVec.x += 1;
    if (dirVec.lengthSq() > 0) {
      dirVec.normalize().multiplyScalar(speed * dt);
      player.position.add(dirVec);
    }

    // Grapple movement
    if (hookTarget) {
      const toTarget = new THREE.Vector3().subVectors(hookTarget, player.position);
      const dist = toTarget.length();
      if (dist > 0.4) {
        const move = Math.min(hookSpeed * dt, dist);
        toTarget.normalize().multiplyScalar(move);
        player.position.add(toTarget);
        // update line
        hookLine.geometry.setFromPoints([player.position.clone(), hookTarget.clone()]);
      } else {
        // arrived
        scene.remove(hookLine);
        hookLine = null;
        hookTarget = null;
      }
    }

    // Simple pickup
    if (player.position.distanceTo(loot.position) < 1.6) {
      // simulate selfish pickup decreasing trust
      trust = Math.max(0, trust - 12);
      setTrust(trust);
      loot.position.set((Math.random()-0.5)*20, 0.6, (Math.random()-0.5)*20);
      showNotice("Loot picked. Trust -12");
    }

    // camera follow
    const camTarget = new THREE.Vector3().copy(player.position).add(new THREE.Vector3(0,9,12));
    camera.position.lerp(camTarget, 0.08);
    camera.lookAt(player.position);

    renderer.render(scene, camera);
    requestAnimationFrame(animate);
  }

  // Notice system
  let noticeTimeout;
  function showNotice(text){
    const elId = '__notice';
    let el = document.getElementById(elId);
    if (!el) {
      el = document.createElement('div'); el.id = elId; el.className = 'notice';
      document.body.appendChild(el);
    }
    el.textContent = text;
    clearTimeout(noticeTimeout);
    noticeTimeout = setTimeout(()=>{ el.remove(); }, 2000);
  }

  animate();
}

