:root {
  --bg-1: #0b1020;
  --bg-2: #111827;
  --panel: rgba(10, 16, 28, 0.78);
  --line: rgba(148, 163, 184, 0.3);
  --green: #34d399;
  --amber: #fbbf24;
  --red: #f87171;
  --cyan: #67e8f9;
  --purple: #a78bfa;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: radial-gradient(circle at top, #16213d 0%, #0b1020 35%, #090d16 100%);
  color: white;
  font-family: Inter, system-ui, -apple-system, sans-serif;
}

body {
  display: grid;
  place-items: center;
}

#game-shell {
  position: relative;
  width: min(96vw, 1280px);
  height: min(92vh, 720px);
  border: 1px solid var(--line);
  border-radius: 18px;
  overflow: hidden;
  background: linear-gradient(180deg, rgba(17,24,39,.96), rgba(15,23,42,.96));
  box-shadow: 0 30px 80px rgba(0,0,0,.5);
}

canvas {
  width: 100%;
  height: 100%;
  display: block;
  background: linear-gradient(180deg, #18233d 0%, #0f172a 50%, #0b1020 100%);
}

#hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

#topbar {
  position: absolute;
  top: 18px;
  left: 18px;
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.tag {
  padding: 7px 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.7);
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #dbeafe;
}

#hero-switcher {
  position: absolute;
  top: 18px;
  right: 18px;
  display: flex;
  gap: 8px;
  pointer-events: auto;
}

.hero-btn {
  border: 1px solid rgba(255,255,255,.12);
  background: rgba(10,16,28,.9);
  color: white;
  border-radius: 12px;
  padding: 8px 12px;
  cursor: pointer;
  font-weight: 600;
  transition: 0.2s ease;
}

.hero-btn.active {
  background: linear-gradient(135deg, var(--purple), var(--cyan));
  color: #07111d;
  border-color: transparent;
}

#trust-panel {
  position: absolute;
  left: 18px;
  bottom: 18px;
  width: 260px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(15,23,42,.72);
  backdrop-filter: blur(8px);
}

.label {
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #cbd5e1;
  margin-bottom: 8px;
}

.bar {
  width: 100%;
  height: 12px;
  border-radius: 999px;
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.1);
  overflow: hidden;
}

#trust-fill {
  width: 60%;
  height: 100%;
  background: linear-gradient(90deg, var(--green), var(--amber), var(--red));
  transition: width 0.18s ease;
}

#trust-text {
  margin-top: 8px;
  font-weight: 700;
  color: #d1fae5;
  font-size: 12px;
}

#objective {
  position: absolute;
  right: 18px;
  bottom: 18px;
  max-width: 360px;
  padding: 12px 14px;
  border-radius: 12px;
  background: rgba(7, 10, 17, .7);
  border: 1px solid var(--line);
  font-size: 13px;
  color: #e2e8f0;
}

#phone {
  position: absolute;
  right: 30px;
  top: 76px;
  width: 280px;
  border-radius: 18px;
  border: 1px solid rgba(255,255,255,.16);
  background: rgba(8, 12, 20, .95);
  box-shadow: 0 18px 40px rgba(0,0,0,.45);
  overflow: hidden;
  pointer-events: none;
}

#phone.hidden {
  display: none;
}

.phone-header {
  display: flex;
  justify-content: space-between;
  padding: 12px 16px;
  background: rgba(236,72,153,.14);
  border-bottom: 1px solid rgba(255,255,255,.08);
  font-weight: 700;
}

.signal {
  color: var(--cyan);
}

.phone-body {
  padding: 14px;
}

.message {
  background: rgba(15,23,42,.9);
  border: 1px solid rgba(103,232,249,.18);
  border-radius: 12px;
  padding: 12px;
  margin-bottom: 10px;
}

.message strong {
  color: var(--cyan);
}

.message p {
  margin: 8px 0 0;
  color: #e2e8f0;
  font-size: 13px;
  line-height: 1.5;
}
